 static void patch(ClassNode c){if(c.name.equals(A)){
  var m=new MethodNode(ACC_STATIC,"nativeSourceNpcReactionLive","(L"+PC+";L"+A+"$Ref;)Ljava/lang/Object;",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,A,"live","(L"+PC+";L"+A+"$Ref;)L"+A+"$Live;",false));m.instructions.add(new InsnNode(ARETURN));c.methods.add(m);return;
 }
 int ports=0;for(var m:c.methods)if(List.of("publishNpcCounterBarrierTrigger","publishNpcCounterMirrorTrigger").contains(m.name)){
  var calls=Arrays.stream(m.instructions.toArray()).filter(n->n instanceof MethodInsnNode call&&call.owner.equals(PC)&&call.name.equals("sendEncrypted")).map(n->(MethodInsnNode)n).toList();if(calls.size()!=2)throw new AssertionError("one effect then one reaction port");var call=calls.get(1);if(!call.desc.equals("([BLjava/lang/String;)V"))throw new AssertionError("same encrypted sender ABI");
  var pass=new LabelNode();var end=new LabelNode();var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(LLOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,N,"allow","(L"+PC+";J)Z",false));x.add(new JumpInsnNode(IFNE,pass));x.add(new InsnNode(POP));x.add(new InsnNode(POP));x.add(new InsnNode(POP));x.add(new JumpInsnNode(GOTO,end));x.add(pass);m.instructions.insertBefore(call,x);m.instructions.insert(call,end);ports++;
 }if(ports!=2)throw new AssertionError("two original NPC reflected reaction sends");}
 public static void main(String[]a)throws Exception{var urls=new ArrayList<java.net.URL>();urls.add(Path.of(a[1]).toUri().toURL());try(var f=Files.list(Path.of(a[3]))){for(var p:f.filter(x->x.toString().endsWith(".jar")).toList())urls.add(p.toUri().toURL());}try(var hierarchy=new java.net.URLClassLoader(urls.toArray(java.net.URL[]::new),ClassLoader.getPlatformClassLoader());var base=new JarFile(a[1])){FreezeAcceptedMethods.hierarchy=hierarchy;for(String name:TARGETS){var c=FreezeAcceptedMethods.read(base,name);patch(c);var canon=new ClassNode();new ClassReader(FreezeAcceptedMethods.bytes(c,true)).accept(canon,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);var bytes=FreezeAcceptedMethods.bytes(canon,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var next=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(next,name),false)))throw new AssertionError(name);}}}System.out.println("PASS NPC reflected reaction two original sends with original ingress Ref/live validation; HP/effect/sender/order bodies retained");}
